def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/wildfire/input/nifc_lightning_caused_acres.csv'
    with open(path, 'r', encoding='utf-8', errors='replace') as f:
        lines = f.readlines()[:40]
    return pd.DataFrame({'line_no': list(range(1, len(lines)+1)), 'line': [l.rstrip('\n') for l in lines]})
